"""RLS session binding fail-closed (060)."""from __future__ import annotationsfrom unittest.mock import AsyncMock, MagicMockimport pytestfrom palatium_ai.infrastructure.database.rls import set_rls_user_scope@pytest.mark.asyncioasync def test_set_rls_user_scope_rejects_empty() -> None:    session = MagicMock()    session.execute = AsyncMock()    with pytest.raises(ValueError, match="non-empty user_id"):        await set_rls_user_scope(session, "  ")    session.execute.assert_not_called()@pytest.mark.asyncioasync def test_set_rls_user_scope_binds_setting() -> None:    session = MagicMock()    session.execute = AsyncMock()    await set_rls_user_scope(session, "user-a")    session.execute.assert_awaited_once()    args, kwargs = session.execute.await_args    # SQLAlchemy TextClause + params dict    assert kwargs == {} or "uid" in str(args) or (len(args) >= 2 and args[1].get("uid") == "user-a")    params = args[1] if len(args) > 1 else {}    assert params["uid"] == "user-a"    assert params["key"] == "palatium.user_id"